import http from 'node:http';import fs from 'node:fs/promises';import path from 'node:path';import {CronExpressionParser} from 'cron-parser';
export interface ScheduleDefinition {scheduleId:string;scriptArtifactId:string;cron:string;timezone:string;enabled:boolean;concurrencyPolicy:'FORBID_OVERLAP'|'ALLOW';}
export class ScheduleRegistry {private map=new Map<string,ScheduleDefinition>();private running=new Set<string>();create(s:ScheduleDefinition){CronExpressionParser.parse(s.cron,{tz:s.timezone});this.map.set(s.scheduleId,s);return s;}pause(id:string){const s=this.must(id);s.enabled=false;}resume(id:string){const s=this.must(id);s.enabled=true;}next(id:string,from:Date){const s=this.must(id);return CronExpressionParser.parse(s.cron,{tz:s.timezone,currentDate:from}).next().toDate();}begin(id:string){const s=this.must(id);if(!s.enabled)throw new Error('SCHEDULE_DISABLED');if(s.concurrencyPolicy==='FORBID_OVERLAP'&&this.running.has(id))throw new Error('OVERLAP_FORBIDDEN');this.running.add(id);}end(id:string){this.running.delete(id);}private must(id:string){const s=this.map.get(id);if(!s)throw new Error('SCHEDULE_NOT_FOUND');return s;}}
export async function startArtifactServer(root:string):Promise<{url:string;close:()=>Promise<void>}>{const server=http.createServer(async(req,res)=>{const rel=decodeURIComponent((req.url||'/').replace(/^\//,''));const file=path.join(root,rel);try{const data=await fs.readFile(file);res.writeHead(200,{'content-type':'application/zip','content-disposition':`attachment; filename="${path.basename(file)}"`});res.end(data);}catch{res.writeHead(404);res.end('not found');}});await new Promise<void>(r=>server.listen(0,'127.0.0.1',()=>r()));const a=server.address();if(!a||typeof a==='string')throw new Error('SERVER_START_FAILED');return{url:`http://1
27.0.0.1:${a.port}`,close:()=>new Promise((resolve,reject)=>server.close(e=>e?reject(e):resolve()))};}
